@Component({
  selector: 'app-special',
  templateUrl: './special.component.html',
  providers: [LoggerService]  // overrides root provider for this component subtree
})
export class SpecialComponent {
  constructor(private logger: LoggerService) {
    // This gets a NEW instance, not the root singleton
  }
}

// Abstract service
@Injectable()
abstract class Logger {
  abstract log(msg: string): void;
}

// Console logger (root)
@Injectable({ providedIn: 'root' })
class ConsoleLogger extends Logger {
  log(msg: string) { console.log(msg); }
}

// In a component, provide a different logger
@Component({
  providers: [{ provide: Logger, useClass: ConsoleLogger }]  // or another class
})
class SomeComponent {
  constructor(private logger: Logger) {}
}
